window.blogDetail = {"blogId":1496147366,"blogType":0,"pubTime":"2017-05-30 20:29","cate":"个人日记","cateHex":"b8f6c8cbc8d5bcc7","title":"我读红楼梦(九) 第七回 送宫花贾琏戏熙风，宴宁府宝玉会秦钟——平淡中凸显神来之笔","commentNum":0,"effect1":1024,"effect2":524294,"ar":0,"block":0,"inproc":false,"appeal":0,"abstract":"第七回，是小说中最平淡的一回，没有什么大事发生。似乎在第五回的高潮过后，作者笔势趋缓，开始描写贾府中日常的生活琐事。尽管第七回平淡无奇，但它的结构却十分巧妙，完全是由一个又一个的意外串联而成，看似毫无章法，细细读去却又是作者的有心设计，这样的笔法笔波澜壮阔，大起大落的，高潮还要难写，作者在平淡中凸显出了深厚的写作功力，为我们展现了一只神来之笔。<br/>第七回一开始，是周瑞家的要去禀报王夫人刘姥姥...","artype":1,"arUins":"","blogid":1496147366,"voteids":0,"pubtime":1496147366,"replynum":0,"category":"个人日记","effect":1024,"exblogtype":0,"sus_flag":false,"friendrelation":[],"lp_type":0,"lp_id":0,"lp_style":0,"lp_flag":0,"orguin":619774944,"orgblogid":1496147366,"mention_uins":[],"attach":[],"comments":[],"html":"","custom_title":"我读红楼梦(九) 第七回 送宫花贾琏戏熙风，宴宁府宝玉会秦钟——平淡中凸显神来之笔","custom_html":"","uniKey":"http://user.qzone.qq.com/619774944/blog/1496147366"}